        group.MapPost("/documents", async (TradeCommand input, HttpContext context, IAntiforgery antiforgery, IBusinessService service, CancellationToken ct) => { await antiforgery.ValidateRequestAsync(context); return await Result(async () => await service.Post(ActorFrom(context.User), input, ct)); }).Produces<Guid>().ProducesProblem(422).ProducesProblem(403);
